-- E-COMMERCE SALES & CUSTOMER ANALYTICS - SEED DATA

-- Synthetic deterministic dataset; seed=42

USE ecommerce_analytics;

SET FOREIGN_KEY_CHECKS=0;

TRUNCATE TABLE shipping;

TRUNCATE TABLE payments;

TRUNCATE TABLE order_items;

TRUNCATE TABLE orders;

TRUNCATE TABLE products;

TRUNCATE TABLE categories;

TRUNCATE TABLE customers;

SET FOREIGN_KEY_CHECKS=1;






































































SELECT 'customers' table_name,COUNT(*) row_count FROM customers UNION ALL SELECT 'categories',COUNT(*) FROM categories UNION ALL SELECT 'products',COUNT(*) FROM products UNION ALL SELECT 'orders',COUNT(*) FROM orders UNION ALL SELECT 'order_items',COUNT(*) FROM order_items UNION ALL SELECT 'payments',COUNT(*) FROM payments UNION ALL SELECT 'shipping',COUNT(*) FROM shipping;